@page "/"

@inject NavigationManager Navigation

<PageTitle>ShipmentTracker Logistics</PageTitle>

<div class="container text-center py-5">
    <h1 class="display-4 mb-3">📦 ShipmentTracker Logistics</h1>
    <p class="lead">Fast, reliable shipment tracking for dispatchers and customers.</p>

    <div class="card mx-auto mt-4 mb-5" style="max-width: 500px;">
        <div class="card-body">
            <h5 class="card-title">Track Your Shipment</h5>
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHT-100001)"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                    Track
                </button>
            </div>
        </div>
    </div>

    <div class="row mt-4">
        <div class="col-md-6 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">🚚 For Customers</h5>
                    <p class="card-text">Enter your tracking number above to get real-time status updates on your shipment, including estimated delivery dates and current location.</p>
                </div>
            </div>
        </div>
        <div class="col-md-6 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">📋 For Dispatchers</h5>
                    <p class="card-text">Log in to access the dispatcher dashboard. Create shipments, update statuses, and manage all deliveries from one place.</p>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    private string? trackingNumber;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
            Navigation.NavigateTo($"/track/{trackingNumber.Trim()}");
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            TrackShipment();
    }
}

