@page "/shipments"
@attribute [Authorize]
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Shipments Dashboard</PageTitle>

<h2 class="mb-4">📋 Shipments Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search tracking # or destination..."
               @bind="searchTerm" @bind:event="oninput" @bind:after="LoadShipments" />
    </div>
    <div class="col-md-3 ms-auto text-end">
        <button class="btn btn-success" @onclick="ToggleNewForm">
            @(showNewForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>
</div>

@if (showNewForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
