+               @bind="searchTerm" @bind:event="oninput" @bind:after="LoadShipments" />
+    </div>
+    <div class="col-md-3 ms-auto text-end">
+        <button class="btn btn-success" @onclick="ToggleNewForm">
+            @(showNewForm ? "Cancel" : "+ New Shipment")
+        </button>
+    </div>
+</div>
+
+@if (showNewForm)
+{
+    <div class="card mb-4">
+        <div class="card-body">
+            <h5>Create New Shipment</h5>
+            <div class="row g-2">
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
+                </div>
+                <div class="col-md-3">
+                    <label class="form-label small">Estimated Delivery</label>
+                    <input type="date" class="form-control" @bind="estimatedDelivery" />
+                </div>
+                <div class="col-md-2 d-flex align-items-end">
+                    <button class="btn btn-primary" @onclick="CreateShipment">Create</button>
+                </div>
+            </div>
+            @if (!string.IsNullOrEmpty(createError))
+            {
+                <div class="alert alert-danger mt-2">@createError</div>
+            }
+        </div>
+    </div>
+}
+
+@if (loading)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else if (shipments is null || shipments.Count == 0)
+{
+    <p class="text-muted">No shipments found.</p>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead>
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Status</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var s in shipments)
+                {
+                    <tr>
+                        <td><strong>@s.TrackingNumber</strong></td>
+                        <td>@s.Origin</td>
+                        <td>@s.Destination</td>
+                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
+                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
+                        <td>
+                            <div class="d-flex align-items-center gap-2">
+                                <select class="form-select form-select-sm" style="width: auto;"
+                                        value="@s.Status" @onchange="e => UpdateStatus(s.Id, e)">
+                                    @foreach (var st in Enum.GetValues<ShipmentStatus>())
+                                    {
+                                        <option value="@st" selected="@(st == s.Status)">@st</option>
+                                    }
+                                </select>
+                            </div>
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    private List<Shipment>? shipments;
+    private bool loading = true;
+    private string statusFilter = "";
+    private string searchTerm = "";
+    private bool showNewForm;
+    private Shipment newShipment = new();
+    private DateTime? estimatedDelivery;
+    private string? createError;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        loading = true;
+        try
+        {
+            shipments = await ShipmentService.GetShipmentsAsync(
+                string.IsNullOrEmpty(statusFilter) ? null : statusFilter,
+                string.IsNullOrEmpty(searchTerm) ? null : searchTerm);
+        }
+        catch
+        {
+            shipments = [];
+        }
+        loading = false;
+    }
+
+    private void ToggleNewForm()
+    {
+        showNewForm = !showNewForm;
+        if (showNewForm)
+        {
+            newShipment = new Shipment();
+            estimatedDelivery = null;
+            createError = null;
+        }
+    }
+
+    private async Task CreateShipment()
+    {
+        createError = null;
+        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))
+        {
+            createError = "Origin and Destination are required.";
+            return;
+        }
+        try
+        {
+            newShipment.EstimatedDelivery = estimatedDelivery;
+            await ShipmentService.CreateShipmentAsync(newShipment);
+            showNewForm = false;
+            await LoadShipments();
+        }
+        catch (Exception ex)
+        {
+            createError = $"Failed to create shipment: {ex.Message}";
+        }
+    }
+
+    private async Task UpdateStatus(int id, ChangeEventArgs e)
+    {
+        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
+        {
+            try
+            {
+                await ShipmentService.UpdateStatusAsync(id, newStatus);
+                await LoadShipments();
+            }
+            catch
+            {
+                // Reload to show current state
+                await LoadShipments();
+            }
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info text-dark",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

