+@page "/track"
+@page "/track/{TrackingNumber}"
+@attribute [AllowAnonymous]
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+@inject IShipmentService ShipmentService
+
+<PageTitle>Track Shipment</PageTitle>
+
+<h2 class="mb-4">🔍 Track Your Shipment</h2>
+
+<div class="input-group mb-4" style="max-width: 500px;">
+    <input type="text" class="form-control" placeholder="Enter tracking number..."
+           @bind="inputTrackingNumber" @bind:event="oninput"
+           @onkeydown="HandleKeyDown" />
+    <button class="btn btn-primary" @onclick="DoTrack" disabled="@string.IsNullOrWhiteSpace(inputTrackingNumber)">
+        Track
+    </button>
+</div>
+
+@if (loading)
+{
+    <p><em>Looking up shipment...</em></p>
+}
+else if (notFound)
+{
+    <div class="alert alert-warning" style="max-width: 500px;">
+        <strong>Shipment not found.</strong> Please check the tracking number and try again.
+    </div>
+}
+else if (shipment is not null)
+{
+    <div class="card" style="max-width: 600px;">
+        <div class="card-header">
+            <strong>@shipment.TrackingNumber</strong>
+        </div>
+        <div class="card-body">
+            <!-- Progress indicator -->
+            <div class="mb-4">
+                <div class="d-flex justify-content-between mb-1 small">
+                    @foreach (var step in progressSteps)
+                    {
+                        <span class="text-center" style="flex:1;">@step</span>
+                    }
+                </div>
+                <div class="progress" style="height: 8px;">
+                    <div class="progress-bar @GetProgressColor()" role="progressbar"
+                         style="width: @GetProgressPercent()%"></div>
+                </div>
+                <div class="d-flex justify-content-between mt-1">
+                    @foreach (var step in progressSteps)
+                    {
+                        var idx = Array.IndexOf(progressSteps, step);
+                        <span class="text-center" style="flex:1;">
+                            @if (idx <= GetStepIndex())
+                            {
+                                <span class="text-success">●</span>
+                            }
+                            else
+                            {
+                                <span class="text-muted">○</span>
+                            }
+                        </span>
+                    }
+                </div>
+            </div>
+
+            <table class="table table-borderless mb-0">
+                <tr><th style="width:160px;">Status</th><td><span class="badge @GetBadgeClass()">@shipment.Status</span></td></tr>
+                <tr><th>Origin</th><td>@shipment.Origin</td></tr>
+                <tr><th>Destination</th><td>@shipment.Destination</td></tr>
+                <tr><th>Recipient</th><td>@shipment.RecipientName</td></tr>
+                <tr><th>Created</th><td>@shipment.CreatedDate.ToString("MMM dd, yyyy h:mm tt")</td></tr>
+                <tr><th>Est. Delivery</th><td>@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td></tr>
+                @if (!string.IsNullOrEmpty(shipment.Description))
+                {
+                    <tr><th>Description</th><td>@shipment.Description</td></tr>
+                }
+            </table>
+        </div>
+    </div>
+}
+
+@code {
+    [Parameter] public string? TrackingNumber { get; set; }
+
+    private string? inputTrackingNumber;
+    private Shipment? shipment;
+    private bool loading;
+    private bool notFound;
+
+    private static readonly string[] progressSteps = ["Pending", "Picked Up", "In Transit", "Out for Delivery", "Delivered"];
+
+    protected override async Task OnParametersSetAsync()
+    {
+        if (!string.IsNullOrEmpty(TrackingNumber))
+        {
+            inputTrackingNumber = TrackingNumber;
+            await FetchShipment(TrackingNumber);
+        }
+    }
+
+    private async Task DoTrack()
+    {
+        if (!string.IsNullOrWhiteSpace(inputTrackingNumber))
+            await FetchShipment(inputTrackingNumber.Trim());
+    }
+
+    private void HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            _ = DoTrack();
+    }
+
+    private async Task FetchShipment(string trackingNum)
+    {
+        loading = true;
+        notFound = false;
+        shipment = null;
+        StateHasChanged();
+
+        shipment = await ShipmentService.GetByTrackingNumberAsync(trackingNum);
+        notFound = shipment is null;
+        loading = false;
+    }
+
+    private int GetStepIndex()
+    {
+        if (shipment is null) return -1;
+        return shipment.Status switch
+        {
+            ShipmentStatus.Pending => 0,
+            ShipmentStatus.PickedUp => 1,
+            ShipmentStatus.InTransit => 2,
+            ShipmentStatus.OutForDelivery => 3,
+            ShipmentStatus.Delivered => 4,
+            ShipmentStatus.Cancelled => -1,
+            _ => -1
+        };
+    }
+
+    private int GetProgressPercent()
+    {
+        var idx = GetStepIndex();
+        if (idx < 0) return 0;
+        return idx * 25;
+    }
+
+    private string GetProgressColor() => shipment?.Status == ShipmentStatus.Cancelled ? "bg-danger" : "bg-success";
+
+    private string GetBadgeClass() => shipment?.Status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info text-dark",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

